{
  "technical_and_design_decisions": [
    "Implement in Go, following existing fabric-config library patterns (e.g., protobuf ConfigGroup modifications).",
    "U1: Add a function (e.g., AddConsortium) to create a consortium group; allow empty org list but update examples to add orgs afterwards.",
    "U2: Provide a variant of config update generation that returns cb.ConfigUpdateEnvelope without requiring signing identities, keeping existing signed path.",
    "U3: Add RemoveLegacyOrdererAddresses on the channel group; make top-level OrdererAddresses read-only (no setter) and require org-level endpoints in genesis creation.",
    "U4: Add RemoveKafkaBrokers analogous to legacy orderer address removal.",
    "U5: Implement AddConsenter/RemoveConsenter for etcdraft; RemoveConsenter matches all four fields (host, port, client TLS cert, server TLS cert).",
    "U7: Add granular setter methods on OrdererGroup (SetMaxMessageCount, SetAbsoluteMaxBytes, SetPreferredMaxBytes, SetBatchTimeout, SetMaxChannels, SetConsensusType, SetConsensusState, raft metadata helpers) that preserve other fields; keep Get/SetConfiguration.",
    "U8: Add granular MSP cert/OU/CRL setters/removers on OrdererOrgGroup, ApplicationOrgGroup, ConsortiumOrgGroup; reuse existing cert validation; keep Get/SetMSP.",
    "U6: Build a Go CLI 'configtx' with 'update' subcommand consuming batchUpdate.json, connectionProfile.json, signingIdentities.json; use service discovery to fetch config blocks; support --dryrun and stacked operations; map operations to library functions.",
    "Testing will use Go standard testing; integration tests may mock discovery or use test fixtures."
  ],
  "assumptions": [
    "Developer is a single experienced Go/Hyperledger Fabric engineer with the existing fabric-config codebase available.",
    "Existing similar API methods (AddCapability, AddOrdererEndpoint, AddAnchorPeer) can be used as templates.",
    "The connection profile format matches the standard Fabric format linked in the spec and peer discovery is available.",
    "Effort includes writing unit/integration tests and updating in-repo Go examples, but excludes separate user documentation and external QA.",
    "No production deployment, release management, or manual network setup is included.",
    "The CLI tool is delivered as part of the fabric-config repository.",
    "Cert validation can rely on existing fabric crypto utilities; no new cryptographic code is required."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Analysis and API design",
      "activity_description": "Review existing fabric-config library, design signatures and behavior for all new API functions and CLI, define error handling and data flows.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Add consortium function",
      "activity_description": "Implement function to add a new consortium to the consortiums group, handle empty org edge case, and initial example scaffolding.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Unsigned config update envelope",
      "activity_description": "Implement function that returns cb.ConfigUpdateEnvelope without requiring signing identities, refactoring existing update path.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4",
      "activity_name": "U3: Remove legacy orderer addresses",
      "activity_description": "Implement RemoveLegacyOrdererAddresses on channel group, prevent updates to top-level OrdererAddresses, adjust genesis block creation to require org-level endpoints.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A5",
      "activity_name": "U4: Remove KafkaBrokers",
      "activity_description": "Implement function to remove KafkaBrokers section from config, analogous to legacy orderer address removal.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: Consenter add/remove",
      "activity_description": "Implement AddConsenter and RemoveConsenter functions for etcdraft orderer configuration, with exact 4-field matching for removal.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "U7: Orderer group individual setters",
      "activity_description": "Implement granular setter methods on OrdererGroup (batch size fields, batch timeout, max channels, consensus type/state, raft metadata options) preserving other values.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "A8",
      "activity_name": "U8: Org MSP individual setters",
      "activity_description": "Implement granular MSP cert/OU/CRL setters and removers for OrdererOrgGroup, ApplicationOrgGroup, ConsortiumOrgGroup, with cert validation reuse.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A9",
      "activity_name": "U6 CLI: Scaffolding and input parsing",
      "activity_description": "Create CLI binary, parse batchUpdate.json, connectionProfile.json, signingIdentities.json, implement --dryrun flag and error handling for unsupported operations.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "U6 CLI: Bulk operations mapping",
      "activity_description": "Implement stacked operations (update MSP, add/remove anchor peers, add/remove/update consenters, TLS cert updates) mapping JSON to fabric-config library calls.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A11",
      "activity_name": "U6 CLI: Fetch and submit",
      "activity_description": "Integrate service discovery via connection profile to fetch config blocks, sign with provided identities, and submit config update transactions.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A12",
      "activity_name": "Update examples",
      "activity_description": "Update Go examples for U1, U3, U4, U5, U7, U8 and improve migration examples (Kafka to EtcdRaft, v1 to v2) demonstrating new APIs.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A13",
      "activity_name": "Unit tests for library",
      "activity_description": "Write unit tests covering all new API functions (consortium, unsigned update, removals, consenters, orderer setters, MSP setters).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A14",
      "activity_name": "Integration tests for CLI and migrations",
      "activity_description": "Write integration tests for CLI bulk operations, dry-run output, and end-to-end config updates using test fixtures or mocked discovery.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A15",
      "activity_name": "Final review and polish",
      "activity_description": "Self code review, fix defects, verify acceptance criteria, minor refactors, ensure build and tests pass.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 39.5
  }
}

